{
     "title": "CSCI-630: Foundations of Artificial Intelligence",
     "learningObjectives": [
       "Define the core components of a computer vision pipeline and explain how each stage processes image data.",
       "Explain how geometric transforms and feature methods enable coordinate mapping and pattern recognition in AI systems.",
       "Evaluate the impact of sampling, illumination, and noise on computer vision results and identify evaluation metrics for robustness."
     ],
     "beats": [
       {
         "title": "Pipeline Foundations",
         "claim": "A rigorous computer vision pipeline states the task, representation, assumptions, supervision, and decision rule.",
         "example": "A self-driving car system defines the task as lane detection, uses grayscale images as representation, assumes consistent lighting, relies on labeled training data for supervision, and applies a threshold-based decision rule to classify as "
         , "visualDirection": "Show a flowchart with five labeled boxes: Task, Representation, Assumptions, Supervision, Decision Rule. Arrow connects each box sequentially.",
         "sourceIds": ["rit-csci-630"]
       },
       {
         "title": "Image Representation",
         "claim": "Computer vision pipelines represent images as numeric arrays.",
         "example": "A 100x100 pixel grayscale image becomes a 10000-element array where each value ranges from 0 to 255.",
         "visualDirection": "Display a small grid of pixel values next to a corresponding numeric array representation. Highlight the mapping between spatial coordinates and array indices.",
         "sourceIds": ["opencv-documentation"]
       },
       {
         "title": "Color Conversion",
         "claim": "Color conversion changes the coordinate representation of pixel values.",
         "example": "Converting an RGB image to HSV separates color information from brightness, allowing algorithms to isolate specific hues regardless of lighting intensity.",
         "visualDirection": "Show a side-by-side comparison of an RGB image and its HSV equivalent, with a legend explaining how hue channels isolate color data.",
         "sourceIds": ["opencv-documentation"]
       },
       {
         "title": "Filtering",
         "claim": "Filtering combines neighboring samples to smooth, sharpen, or detect structure.",
         "example": "A Gaussian blur filter averages adjacent pixel values to reduce sensor noise and highlight large-scale object boundaries.",
         "visualDirection": "Display a noisy image, a filtered image, and a sliding window overlay showing how neighboring pixels are averaged.",
         "sourceIds": ["opencv-documentation"]
       },
       {
         "title": "Feature Methods",
         "claim": "Feature methods locate and describe repeatable image patterns.",
         "example": "SIFT (Scale-Invariant Feature Transform) identifies keypoints and generates descriptors that remain consistent across scale and rotation changes.",
         "visualDirection": "Show an image with detected keypoints marked as circles, connected by lines to corresponding keypoints in a transformed image.",
         "sourceIds": ["opencv-documentation"]
       },
       {
         "title": "Calibration",
         "claim": "Calibration estimates camera parameters needed for geometric measurement.",
         "example": "Using a chessboard pattern, the system calculates focal length and principal point to map 2D image coordinates to 3D space accurately.",
         "visualDirection": "Display a chessboard grid overlaid on a real-world scene, with a diagram showing the projection matrix transforming 2D to 3D coordinates.",
         "sourceIds": ["opencv-documentation"]
       },
       {
         "title": "Geometric Transforms",
         "claim": "Geometric transforms map coordinates between image representations.",
         "example": "Affine transformation adjusts image coordinates to correct perspective distortion in a tilted photograph.",
         "visualDirection": "Show a distorted image and a corrected image, with a transformation matrix displayed alongside the coordinate mapping lines.",
         "sourceIds": ["opencv-documentation"]
       },
       {
         "title": "Segmentation",
         "claim": "Segmentation assigns pixels or regions to selected categories.",
         "example": "Thresholding separates foreground objects from the background by classifying pixels based on intensity values above or below a set level.",
         "visualDirection": "Display a binary mask where foreground objects are white and background is black, overlaid on the original image.",
         "sourceIds": ["opencv-documentation"]
       },
       {
         "title": "Motion Methods",
         "claim": "Motion methods compare observations across time.",
         "example": "Optical flow calculates pixel displacement between consecutive frames to track object movement and estimate velocity.",
         "visualDirection": "Show a sequence of three frames with vector arrows indicating pixel movement from frame to frame.",
         "sourceIds": ["opencv-documentation"]
       },
       {
         "title": "Evaluation & Robustness",
         "claim": "Results depend on sampling, illumination, noise, training data, thresholds, and evaluation metrics.",
         "example": "Varying the threshold value changes the number of detected edges, demonstrating how sensitivity to illumination and noise affects detection accuracy.",
         "visualDirection": "Display a slider adjusting a threshold value, with corresponding binary masks showing how edge detection changes as the threshold shifts.",
         "sourceIds": ["opencv-documentation"]
       }
     ]
   }
